import{_t as e,it as t,n,rt as r}from"./chunks/framework.gd_RGE3V.js";import"./chunks/assets.CGKUPeQw.js";var i=JSON.parse(`{"title":"AireGlu Release Notes","description":"","frontmatter":{},"headers":[],"relativePath":"aireblock-releases/AireGlu/aireglu-v1-126-0.md","filePath":"aireblock-releases/AireGlu/aireglu-v1-126-0.md","lastUpdated":1794501798000}`),a={name:`aireblock-releases/AireGlu/aireglu-v1-126-0.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="aireglu-release-notes" tabindex="-1"><span class="fsc-product"><img src="/aireglu-icon.png"> AireGlu Release Notes</span> <a class="header-anchor" href="#aireglu-release-notes" aria-label="Permalink to “AireGlu Release Notes”">​</a></h1><blockquote><p><strong>Version:</strong> 1.126.0<br><strong>Release Date:</strong> 18 November 2026</p></blockquote><h4 id="✨-new-features" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features" aria-label="Permalink to “✨ New Features”">​</a></h4><ul><li>Enhanced Role-Based Permissions for MCP Servers (GLU-3300)</li><li>Mandatory Key Format Selection (GLU-3235)</li></ul><h1 id="detailed-changes" tabindex="-1">Detailed Changes <a class="header-anchor" href="#detailed-changes" aria-label="Permalink to “Detailed Changes”">​</a></h1><h3 id="✨-new-features-1" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-1" aria-label="Permalink to “✨ New Features”">​</a></h3><hr><h4 id="improved-role-based-access-for-mcp-servers-glu-3300" tabindex="-1">Improved Role-Based Access for MCP Servers (GLU-3300) <a class="header-anchor" href="#improved-role-based-access-for-mcp-servers-glu-3300" aria-label="Permalink to “Improved Role-Based Access for MCP Servers (GLU-3300)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>The system now validates resource-based permissions when logging in. If a user&#39;s role does not include access to a specific MCP server, connectivity to that server will be blocked. This provides granular control for tenant administrators to restrict server access as needed.</p></div><div class="tip custom-block"><p class="custom-block-title">What this means for you</p><p>You and your organisation now have finer control over server access. Administrators can assign specific permissions to users, ensuring that individuals only have access to the MCP servers required for their role. This enhances security and data handling compliance by preventing unauthorised access to tools.</p></div><h4 id="mandatory-file-format-selection-glu-3235" tabindex="-1">Mandatory File Format Selection (GLU-3235) <a class="header-anchor" href="#mandatory-file-format-selection-glu-3235" aria-label="Permalink to “Mandatory File Format Selection (GLU-3235)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>The Key Format field for connections (such as client credentials or JWT Bearer) will no longer use a default value. You are required to explicitly select the correct file format for your private key upon creation. This change reduces the risk of misconfiguration and authentication failures.</p></div><div class="tip custom-block"><p class="custom-block-title">What this means for you</p><p>You can no longer accidentally use the wrong key format during the creation of new connections. The system forces you to choose the correct format for your private key, which helps prevent errors that could stop login or communication issues from occurring later.</p></div>`,13)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};